import React, { useState, useEffect } from 'react';
import './Calendrier.css';
import AjouterTrajet from './AjouterTrajet';

const Calendrier = () => {
  const [activeTab, setActiveTab] = useState("Semaine");
  const [selectedPerson, setSelectedPerson] = useState("Tous");
  const [currentDate, setCurrentDate] = useState(new Date());
  const [showModal, setShowModal] = useState(false);

  // Onglets principaux
  const tabs = ["Aujourd'hui", "À venir", "Passées", "Personne", "Semaine"];

  // Données des personnes
  const personnesList = [
    { id: 1, name: 'Loïc', role: 'Chauffeur', statut: 'Disponible', trajets: 12 },
    { id: 2, name: 'Paul', role: 'Chauffeur', statut: 'En trajet', trajets: 8 },
    { id: 3, name: 'Jose', role: 'Coordinateur', statut: 'Disponible', trajets: 15 },
    { id: 4, name: 'Jean', role: 'Chauffeur', statut: 'Congés', trajets: 10 },
    { id: 5, name: 'Jase', role: 'Assistant', statut: 'Disponible', trajets: 6 }
  ];

  // Données du planning
  const joursSemaine = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];
  const timeSlots = Array.from({ length: 24 }, (_, i) => `${String(i).padStart(2, '0')}:00`);

  // État global de tous les trajets
  const [allTrajets, setAllTrajets] = useState([]);

  useEffect(() => {
    fetch('http://localhost:3001/api/calendrier/today')
      .then(res => res.json())
      .then(data => setAllTrajets(data))
      .catch(() => setAllTrajets([
        { id: 1, heure: '08:30', heureFin: '10:00', date: 'Aujourd\'hui', client: 'Hôpital Central', personne: 'Loïc', statut: 'En cours' },
        { id: 2, heure: '10:15', heureFin: '11:30', date: 'Aujourd\'hui', client: 'Clinique Nord', personne: 'Marie', statut: 'À venir' },
        { id: 3, heure: '14:00', heureFin: '15:30', date: 'Aujourd\'hui', client: 'Centre Médical', personne: 'Paul', statut: 'À venir' },
      ]));
  }, []);

  const handleSaveTrajet = async (trajetData) => {
    const dateLabel = trajetData.dateDebut || "Aujourd'hui";
    const newTrajet = {
      id: Date.now(),
      heure: trajetData.heureDebut || '08:00',
      heureFin: trajetData.heureFin || '09:00',
      date: dateLabel,
      client: trajetData.nom || 'Nouveau trajet',
      personne: trajetData.personnes?.length > 0 ? trajetData.personnes[0].nom : 'Non assigné',
      statut: 'Planifié',
      from: trajetData.adresse || '',
      to: '',
    };

    try {
      const response = await fetch('http://localhost:3001/api/calendrier/trajet', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(trajetData)
      });
      const saved = await response.json();
      setAllTrajets(prev => [...prev, { ...newTrajet, ...saved }]);
    } catch {
      setAllTrajets(prev => [...prev, newTrajet]);
    }
    setShowModal(false);
  };

  const getStartOfWeek = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
  };

  const getEndOfWeek = (date) => {
    const start = getStartOfWeek(date);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return end;
  };

  const getWeekDays = () => {
    const start = getStartOfWeek(currentDate);
    const days = [];
    for (let i = 0; i < 7; i++) {
      const day = new Date(start);
      day.setDate(start.getDate() + i);
      days.push({ name: joursSemaine[i], date: day });
    }
    return days;
  };

  // HELPERS FOR ABSOLUTE POSITIONING
  const timeToMinutes = (time) => {
    if (!time) return 0;
    const [h, m] = time.split(':').map(Number);
    return h * 60 + (m || 0);
  };

  const getTripTop = (heure) => {
    const mins = timeToMinutes(heure);
    return (mins / (24 * 60)) * 100;
  };

  const getTripHeight = (start, end) => {
    const startMins = timeToMinutes(start);
    const endMins = timeToMinutes(end || start);
    let diff = endMins - startMins;
    if (diff <= 0) diff = 60; // 1 hour default
    return (diff / (24 * 60)) * 100;
  };

  const renderContent = () => {
    switch (activeTab) {
      case "Aujourd'hui":
        return (
          <div className="content-today">
            <div className="today-header">
              <h2>{currentDate.toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' })}</h2>
            </div>
            <div className="trajets-list">
              {allTrajets.filter(t => t.date === 'Aujourd\'hui' || t.date === currentDate.toLocaleDateString('fr-FR')).map(trajet => (
                <div key={trajet.id} className="trajet-item">
                  <div className="trajet-time">{trajet.heure} - {trajet.heureFin}</div>
                  <div className="trajet-info">
                    <div className="trajet-client">{trajet.client}</div>
                    <div className="trajet-person">avec {trajet.personne}</div>
                  </div>
                  <div className={`trajet-statut ${trajet.statut.toLowerCase().replace(' ', '-')}`}>{trajet.statut}</div>
                </div>
              ))}
            </div>
          </div>
        );

      case "Semaine":
        const weekDays = getWeekDays();
        return (
          <div className="content-week">
            <div className="week-navigation">
              <button className="nav-button" onClick={() => { const d = new Date(currentDate); d.setDate(d.getDate() - 7); setCurrentDate(d); }}>‹ Précédent</button>
              <div className="current-week">Semaine du {getStartOfWeek(currentDate).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' })} au {getEndOfWeek(currentDate).toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' })}</div>
              <button className="nav-button" onClick={() => { const d = new Date(currentDate); d.setDate(d.getDate() + 7); setCurrentDate(d); }}>Suivant ›</button>
            </div>

            <div className="calendar-container-wrapper">
              <div className="days-header">
                <div className="time-col-header"></div>
                {weekDays.map(day => (
                  <div key={day.name} className="day-header">
                    <span className="day-name">{day.name}</span>
                    <span className="day-date">{day.date.getDate()}</span>
                  </div>
                ))}
              </div>

              <div className="calendar-grid-body">
                <div className="time-column">
                  {timeSlots.map(time => (
                    <div key={time} className="hour-slot-label">{time}</div>
                  ))}
                </div>

                <div className="days-columns">
                  {weekDays.map(day => {
                    const dayStr = day.date.toLocaleDateString('fr-FR');
                    const isToday = dayStr === new Date().toLocaleDateString('fr-FR');
                    const dayTrajets = allTrajets.filter(t => 
                      t.date === day.name || 
                      t.date === dayStr || 
                      (t.date === "Aujourd'hui" && isToday)
                    );

                    return (
                      <div key={day.name} className={`day-column ${isToday ? 'today' : ''}`}>
                        {timeSlots.map(time => <div key={time} className="hour-grid-line"></div>)}
                        {dayTrajets.map(t => (
                          <div 
                            key={t.id} 
                            className="trip-block"
                            style={{
                              top: `${getTripTop(t.heure)}%`,
                              height: `${getTripHeight(t.heure, t.heureFin)}%`,
                              backgroundColor: getPersonColor(t.personne)
                            }}
                          >
                            <div className="trip-block-time">{t.heure} - {t.heureFin}</div>
                            <div className="trip-block-client">{t.client}</div>
                            <div className="trip-block-person">{t.personne}</div>
                          </div>
                        ))}
                      </div>
                    );
                  })}
                </div>
              </div>
            </div>
          </div>
        );

      default:
        return <div>Sélectionnez une vue</div>;
    }
  };

  const getPersonColor = (name) => {
    const colors = {
      'Loïc': '#e3f2fd',
      'Paul': '#f3e5f5',
      'Jose': '#e8f5e9',
      'Jean': '#fff3e0',
      'Marie': '#fce4ec'
    };
    return colors[name] || '#e3f2fd';
  };

  return (
    <div className="calendrier-wrapper">
      <div className="calendrier-header">
        <div className="tabs-container">
          {tabs.map(tab => (
            <button key={tab} className={`tab-button ${activeTab === tab ? 'active' : ''}`} onClick={() => setActiveTab(tab)}>{tab}</button>
          ))}
        </div>
        <button className="add-trajet-btn" onClick={() => setShowModal(true)}><span>+</span> Ajouter un trajet</button>
      </div>

      <div className="calendrier-content">{renderContent()}</div>

      <AjouterTrajet isOpen={showModal} onClose={() => setShowModal(false)} onSave={handleSaveTrajet} />
    </div>
  );
};

export default Calendrier;
